import{_ as e,c as r,o as t,a0 as n}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Spilleruttalelser","description":"","frontmatter":{},"headers":[],"relativePath":"no/testimonials.md","filePath":"no/testimonials.md"}');const l=e({name:"no/testimonials.md"},[["render",function(e,a,l,i,s,o){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="spilleruttalelser" tabindex="-1">Spilleruttalelser <a class="header-anchor" href="#spilleruttalelser" aria-label="Permalink to &quot;Spilleruttalelser&quot;">​</a></h1><p>Ekte tilbakemeldinger fra elite-petanquespillere som har brukt ressursene til Pétanque Academy for å forbedre sitt mentale spill og konkurranseprestasjoner.</p><div class="tip custom-block"><p class="custom-block-title">Autentisk og anonym</p><p>Disse attestene representerer ekte tilbakemeldinger fra spillere på ulike konkurransenivåer. Alle attester er anonyme for å beskytte spillernes personvern og oppmuntre til ærlig deling.</p></div><h2 id="regionale-og-nasjonale-konkurrenter" tabindex="-1">Regionale og nasjonale konkurrenter <a class="header-anchor" href="#regionale-og-nasjonale-konkurrenter" aria-label="Permalink to &quot;Regionale og nasjonale konkurrenter&quot;">​</a></h2><h3 id="quot-det-indre-coachrammeverket-forandret-alt-quot" tabindex="-1">&quot;Det indre coachrammeverket forandret alt&quot; <a class="header-anchor" href="#quot-det-indre-coachrammeverket-forandret-alt-quot" aria-label="Permalink to &quot;&amp;quot;Det indre coachrammeverket forandret alt&amp;quot;&quot;">​</a></h3><blockquote><p>*«Jeg har spilt konkurransesport i 12 år, og jeg trodde jeg visste alt om petanque. Men jeg var min egen verste fiende – jeg kritiserte meg selv hele tiden etter feil. Rammeverket «Inner Coach vs Inder Critic» fra Mental Strength-modulen ga meg en helt annen måte å snakke med meg selv på under konkurranser.»</p><p><em>Innen to måneder merket lagkameratene mine forskjellen. Jeg var roligere, kom meg raskere etter dårlige kast, og likte faktisk konkurransen igjen. Kom på tredjeplass i regionsmesterskapet i år – mitt beste resultat noensinne.</em></p></blockquote><p><strong>— Regionsmester, Frankrike</strong></p><hr><h3 id="quot-endelig-noen-som-forstar-eliteutvikling-quot" tabindex="-1">&quot;Endelig noen som forstår eliteutvikling&quot; <a class="header-anchor" href="#quot-endelig-noen-som-forstar-eliteutvikling-quot" aria-label="Permalink to &quot;&amp;quot;Endelig noen som forstår eliteutvikling&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Det meste av petanque-treningen handler bare om å &#39;øve mer&#39; eller &#39;jobbe med teknikken din&#39;. Men når du har spilt i over 15 år, er ikke det problemet. Problemet er å få tilgang til teknikken din under press.&quot;</p><p><em>Sonemodulen forklarte nøyaktig hva jeg opplevde – overtenkning under utførelse, å holde meg i analytisk modus når jeg trengte å være i flyt. De praktiske teknikkene for å bytte modus har vært banebrytende.</em></p><p><em>Dette er den første ressursen jeg har funnet som faktisk tar for seg det mentale spillet på elitenivå.</em></p></blockquote><p><strong>— Landslagsspiller, Sverige</strong></p><hr><h3 id="«workshop-metodikken-forvandlet-klubben-var»" tabindex="-1">«Workshop-metodikken forvandlet klubben vår» <a class="header-anchor" href="#«workshop-metodikken-forvandlet-klubben-var»" aria-label="Permalink to &quot;«Workshop-metodikken forvandlet klubben vår»&quot;">​</a></h3><blockquote><p>*«Jeg er klubbtrener, og jeg brukte Workshop-guiden til å kjøre en mental spilløkt med våre 8 beste spillere. Rammeverket for psykologisk trygghet og det strukturerte diskusjonsformatet skapte samtaler vi aldri hadde hatt før.»</p><p><em>Spillerne åpnet seg om sin indre kritiker, sine pressreaksjoner og sine utfordringer med lagkommunikasjon. Det var utrolig sterkt. Vi kjører nå disse øktene månedlig, og lagkulturen har endret seg fullstendig.</em></p></blockquote><p><strong>— Klubbtrener, Tyskland</strong></p><hr><h2 id="turneringsspillere" tabindex="-1">Turneringsspillere <a class="header-anchor" href="#turneringsspillere" aria-label="Permalink to &quot;Turneringsspillere&quot;">​</a></h2><h3 id="quot-praktiske-verktøy-som-faktisk-fungerer-quot" tabindex="-1">&quot;Praktiske verktøy som faktisk fungerer&quot; <a class="header-anchor" href="#quot-praktiske-verktøy-som-faktisk-fungerer-quot" aria-label="Permalink to &quot;&amp;quot;Praktiske verktøy som faktisk fungerer&amp;quot;&quot;">​</a></h3><blockquote><p><em>Jeg har lest bøker om idrettspsykologi før, men de er alltid for generelle eller for akademiske. Målmalen og Dagbokmalen fra Pétanque Academy var akkurat det jeg trengte – praktiske, spesifikke for pétanque og umiddelbart brukbare.</em></p><p><em>Jeg brukte målmalen og hadde en tydelig 3-måneders utviklingsplan på 30 minutter. Dagbokmalen hjelper meg med å spore ikke bare resultater, men også mental ytelse. Disse verktøyene er gull verdt.</em></p></blockquote><p><strong>— Turneringsspiller, Spania</strong></p><hr><h3 id="quot-mindfulness-teknikkene-fungerer-i-konkurranse-quot" tabindex="-1">&quot;Mindfulness-teknikkene fungerer i konkurranse&quot; <a class="header-anchor" href="#quot-mindfulness-teknikkene-fungerer-i-konkurranse-quot" aria-label="Permalink to &quot;&amp;quot;Mindfulness-teknikkene fungerer i konkurranse&amp;quot;&quot;">​</a></h3><blockquote><p><em>Jeg var skeptisk til mindfulness – det virket for «mykt» for konkurranseidrett. Men teknikkene i Mindfulness-modulen er praktiske og spesifikke. 3-pustetilbakestillingen, kroppsskanningen for spenning, øvelsene for fokus i nåtiden.</em></p><p><em>Jeg trener 10 minutter hver morgen, og jeg kan nå bruke disse teknikkene under konkurranser. Når jeg føler at presset øker, har jeg verktøy for å håndtere det. Dette har gjort en målbar forskjell i prestasjonene mine.</em></p></blockquote><p><strong>— Turneringsspiller, Nederland</strong></p><hr><h3 id="«a-forsta-flyttilstander-frigjorde-potensialet-mitt»" tabindex="-1">«Å forstå flyttilstander frigjorde potensialet mitt» <a class="header-anchor" href="#«a-forsta-flyttilstander-frigjorde-potensialet-mitt»" aria-label="Permalink to &quot;«Å forstå flyttilstander frigjorde potensialet mitt»&quot;">​</a></h3><blockquote><p><em>Jeg hadde hatt spill der alt falt på plass – der jeg ikke tenkte, bare spilte perfekt. Men jeg visste ikke hvordan jeg skulle få tilgang til den tilstanden konsekvent. Sonemodulen forklarte vitenskapen bak den og ga meg praktiske teknikker.</em></p><p><em>Å lære om forbigående hypofrontalitet, forstå vekslingen mellom planlegging og utførelse, øve på flytutløsere – denne kunnskapen har gjort disse toppytelsestilstandene mye mer tilgjengelige. Jeg spiller min beste petanque noensinne.</em></p></blockquote><p><strong>— Regional spiller, Frankrike</strong></p><hr><h2 id="lagspillere" tabindex="-1">Lagspillere <a class="header-anchor" href="#lagspillere" aria-label="Permalink to &quot;Lagspillere&quot;">​</a></h2><h3 id="quot-ble-lagkameraten-alle-ønsker-seg-quot" tabindex="-1">&quot;Ble lagkameraten alle ønsker seg&quot; <a class="header-anchor" href="#quot-ble-lagkameraten-alle-ønsker-seg-quot" aria-label="Permalink to &quot;&amp;quot;Ble lagkameraten alle ønsker seg&amp;quot;&quot;">​</a></h3><blockquote><p>*«Jeg var teknisk sterk, men slet i lagkonkurranser. Lagdynamikkmodulen viste meg at det å være en god lagspiller ikke bare handler om å gjøre gode kast – det handler om kommunikasjon, tillit og psykologisk trygghet.»</p><p><em>Jeg lærte å sette ord på tillit, å kommunisere strategi tydelig, å støtte lagkamerater etter feil. I løpet av få måneder gikk jeg fra å bli unngått til å bli ettertraktet som partner. Vant regionalt lagmesterskap i år.</em></p></blockquote><p><strong>— Lagspiller, Italia</strong></p><hr><h3 id="«kommunikasjonsrammeverket-reddet-partnerskapet-vart»" tabindex="-1">«Kommunikasjonsrammeverket reddet partnerskapet vårt» <a class="header-anchor" href="#«kommunikasjonsrammeverket-reddet-partnerskapet-vart»" aria-label="Permalink to &quot;«Kommunikasjonsrammeverket reddet partnerskapet vårt»&quot;">​</a></h3><blockquote><p>*«Min faste partner og jeg hadde spenninger – forskjellige spillestiler, dårlig kommunikasjon og frustrasjon. Team Player-modulen ga oss et rammeverk for å diskutere det konstruktivt.»</p><p><em>Vi lærte om kommunikasjonsmønstre, om å bygge tillit, om å skape psykologisk trygghet. Vi hadde ærlige samtaler ved hjelp av workshopformatet. Partnerskapet vårt er sterkere enn noensinne, og resultatene våre viser det.</em></p></blockquote><p><strong>— Dobbeltlag, Norge</strong></p><hr><h2 id="trenere-og-trenere" tabindex="-1">Trenere og trenere <a class="header-anchor" href="#trenere-og-trenere" aria-label="Permalink to &quot;Trenere og trenere&quot;">​</a></h2><h3 id="«slik-ser-elitecoaching-ut»" tabindex="-1">«Slik ser elitecoaching ut» <a class="header-anchor" href="#«slik-ser-elitecoaching-ut»" aria-label="Permalink to &quot;«Slik ser elitecoaching ut»&quot;">​</a></h3><blockquote><p>*«Jeg har trent petanque i 20 år, mest med fokus på teknikk. Men jeg så spillere med utmerket teknikk mislykkes under press. Utdanningsmodulene ga meg rammeverket for å håndtere det mentale spillet systematisk.»</p><p><em>Treningsleirguiden hjalp meg med å strukturere et helgeprogram som kombinerte teknisk arbeid med mental spilltrening. Tilbakemeldingene fra spillerne var utrolige – de sa at det var den mest verdifulle treningen de noen gang hadde deltatt på.</em></p></blockquote><p><strong>— Trener, Frankrike</strong></p><hr><h3 id="quot-evidensbasert-tilnærming-til-mental-trening-quot" tabindex="-1">&quot;Evidensbasert tilnærming til mental trening&quot; <a class="header-anchor" href="#quot-evidensbasert-tilnærming-til-mental-trening-quot" aria-label="Permalink to &quot;&amp;quot;Evidensbasert tilnærming til mental trening&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Det jeg setter mest pris på er at dette ikke bare er motivasjonstull. Innholdet er basert på faktisk psykologiforskning – flyttilstandsvitenskap, mindfulness-studier og prestasjonspsykologi. Men det er oversatt til praktiske, handlingsrettede teknikker.&quot;</em></p><p><em>Jeg bruker disse modulene som grunnlag for mental spillcoaching med mine elitespillere. Den strukturerte tilnærmingen, de klare rammene, de praktiske øvelsene – dette er innhold på profesjonelt nivå.</em></p></blockquote><p><strong>— Sportspsykolog og petanquetrener, Storbritannia</strong></p><hr><h2 id="vanlige-temaer" tabindex="-1">Vanlige temaer <a class="header-anchor" href="#vanlige-temaer" aria-label="Permalink to &quot;Vanlige temaer&quot;">​</a></h2><h3 id="hva-spillerne-verdsetter-mest" tabindex="-1">Hva spillerne verdsetter mest <a class="header-anchor" href="#hva-spillerne-verdsetter-mest" aria-label="Permalink to &quot;Hva spillerne verdsetter mest&quot;">​</a></h3><p>Basert på tilbakemeldinger fremhever spillerne konsekvent:</p><ol><li><strong>Praktisk, handlingsrettet innhold</strong> – Ikke teori, men teknikker du kan bruke i dag</li><li><strong>Pétanque-spesifikk</strong> - Designet for de unike utfordringene ved petanque</li><li><strong>Fokus på elitenivå</strong> – Tar for seg det mentale spillet, ikke grunnleggende teknikk</li><li><strong>Strukturerte rammeverk</strong> – Tydelige systemer, ikke vage råd</li><li><strong>Gratis og tilgjengelig</strong> – Ingen betalingsmurer, tilgjengelig for alle</li></ol><h3 id="malbare-resultater" tabindex="-1">Målbare resultater <a class="header-anchor" href="#malbare-resultater" aria-label="Permalink to &quot;Målbare resultater&quot;">​</a></h3><p>Spillere rapporterer forbedringer i:</p><ul><li>Konkurranseprestasjon og resultater</li><li>Konsistens under press</li><li>Restitusjonstid etter feil</li><li>Teamkommunikasjon og dynamikk</li><li>Gleden ved konkurranse</li><li>Mental motstandskraft</li></ul><h2 id="del-din-erfaring" tabindex="-1">Del din erfaring <a class="header-anchor" href="#del-din-erfaring" aria-label="Permalink to &quot;Del din erfaring&quot;">​</a></h2><p>Har du brukt ressursene til Pétanque Academy? Vi vil gjerne høre om din erfaring.</p><p><strong>Send din anbefaling på e-post til:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Anbefaling" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Inkludere:</strong></p><ul><li>Ditt erfaringsnivå</li><li>Hvilke ressurser du brukte</li><li>Hvilken innvirkning de hadde</li><li>Om vi kan dele tilbakemeldingen din (navn valgfritt)</li></ul><p>Historien din kan hjelpe andre spillere med å oppdage disse ressursene.</p><hr><h2 id="kom-i-gang" tabindex="-1">Kom i gang <a class="header-anchor" href="#kom-i-gang" aria-label="Permalink to &quot;Kom i gang&quot;">​</a></h2><p>Klar til å utvikle ditt mentale spill?</p><div class="tip custom-block"><p class="custom-block-title">Start her</p><ul><li><strong>Nybegynner med mental trening?</strong> → <a href="/no/utdanning/sonen/">Sonen</a></li><li><strong>Sliter du med press?</strong> → <a href="/no/utdanning/mental-styrke/">Mental styrke</a></li><li><strong>Lagutfordringer?</strong> → <a href="/no/utdanning/lagspiller/">Lagdynamikk</a></li><li><strong>Ønsker du struktur?</strong> → <a href="/no/målmal">Målmal</a></li></ul></div>',64)])])}]]);export{a as __pageData,l as default};
